#!/usr/bin/env -S npx tsx
// =============================================================================
// module-census — the ten largest and the ten most duplicated modules under src/
// =============================================================================
//
// codebase-factoring clause 1: before anything gets split or merged, there has to be a list of
// what's actually oversized or duplicated, committed beside the code and regenerated by a
// command rather than hand-maintained prose that goes stale the day after it's written.
//
// "Largest" is a plain line count per .ts/.tsx file under src/, test files excluded — a fat
// test suite isn't the factoring problem this census is for. "Most duplicated" is a line-level
// Jaccard similarity between every pair of files that each clear a minimum size: every
// non-blank, non-comment-only line is trimmed and put in a set, and a pair's score is
// |intersection| / |union| of those two sets. That catches an exact copy-paste (score 1.0) and
// a near-copy equally well, and it's auditable — rerun the command and recount the overlap by
// hand if a score looks wrong. It is not token-level clone detection (no renamed-variable
// matching); for a census aimed at "which two modules should probably be one," identical lines
// are the signal that matters.
//
// READ-ONLY except for the report file itself. Walks src/, prints nothing destructive, writes
// docs/module-census.md.
//
// Usage:
//     npx tsx scripts/module-census.ts
//     npm run census:modules
// =============================================================================

import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = join(HERE, '..')
const SRC = join(ROOT, 'src')
const OUT = join(ROOT, 'docs', 'module-census.md')

const TOP_N = 10
const MIN_SIGNIFICANT_LINES = 30 // below this, a "97% duplicate" is just two short files

const INCLUDE_EXT = ['.ts', '.tsx']
const EXCLUDE_SUFFIX = ['.test.ts', '.test.tsx', '.spec.ts', '.spec.tsx', '.d.ts']
const EXCLUDE_DIR = new Set(['node_modules', 'dist', 'build', '.git'])

interface FileEntry {
  path: string // relative to repo root
  lines: number
  significant: Set<string> // normalized, deduped, non-trivial lines
}

function walk(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    if (EXCLUDE_DIR.has(name)) continue
    const full = join(dir, name)
    const st = statSync(full)
    if (st.isDirectory()) { walk(full, out); continue }
    if (!INCLUDE_EXT.some((ext) => name.endsWith(ext))) continue
    if (EXCLUDE_SUFFIX.some((suf) => name.endsWith(suf))) continue
    out.push(full)
  }
  return out
}

function isComment(line: string): boolean {
  return line.startsWith('//') || line.startsWith('*') || line.startsWith('/*') || line === '*/'
}

function load(absPath: string): FileEntry {
  const text = readFileSync(absPath, 'utf8')
  const rawLines = text.split('\n')
  const lines = rawLines.length > 0 && rawLines[rawLines.length - 1] === '' ? rawLines.length - 1 : rawLines.length
  const significant = new Set<string>()
  for (const raw of rawLines) {
    const t = raw.trim()
    if (t === '' || isComment(t)) continue
    significant.add(t)
  }
  return { path: relative(ROOT, absPath), lines, significant }
}

function jaccard(a: Set<string>, b: Set<string>): { score: number; shared: number } {
  let shared = 0
  const [small, large] = a.size <= b.size ? [a, b] : [b, a]
  for (const line of small) if (large.has(line)) shared++
  const union = a.size + b.size - shared
  return { score: union === 0 ? 0 : shared / union, shared }
}

const files = walk(SRC).map(load)

const largest = [...files].sort((a, b) => b.lines - a.lines).slice(0, TOP_N)

const candidates = files.filter((f) => f.significant.size >= MIN_SIGNIFICANT_LINES)
const pairs: { a: FileEntry; b: FileEntry; score: number; shared: number }[] = []
for (let i = 0; i < candidates.length; i++) {
  for (let j = i + 1; j < candidates.length; j++) {
    const { score, shared } = jaccard(candidates[i].significant, candidates[j].significant)
    if (shared === 0) continue
    pairs.push({ a: candidates[i], b: candidates[j], score, shared })
  }
}
const mostDuplicated = pairs.sort((x, y) => y.score - x.score).slice(0, TOP_N)

const pct = (n: number) => `${(n * 100).toFixed(1)}%`
const today = new Date().toISOString().slice(0, 10)

const report = `# Module census — ${today}

Regenerate with \`npm run census:modules\` (or \`npx tsx scripts/module-census.ts\`). Committed
beside the code per codebase-factoring clause 1 — this file is the output of a command, not
hand-maintained prose, and the next run replaces it rather than appending to it.

Scope: every \`.ts\`/\`.tsx\` file under \`src/\`, test files (\`*.test.ts(x)\`, \`*.spec.ts(x)\`) and
type-declaration files (\`*.d.ts\`) excluded. ${files.length} files counted.

## Ten largest modules

| # | Lines | Path |
|---|---:|---|
${largest.map((f, i) => `| ${i + 1} | ${f.lines} | \`${f.path}\` |`).join('\n')}

## Ten most duplicated pairs

Line-level Jaccard similarity over non-blank, non-comment-only lines, among files with at least
${MIN_SIGNIFICANT_LINES} such lines. 1.0 means every significant line in the smaller file also
appears in the larger one (an exact copy or a superset); it does not mean the files are
byte-identical.

| # | Similarity | Shared lines | A | B |
|---|---:|---:|---|---|
${mostDuplicated.map((p, i) => `| ${i + 1} | ${pct(p.score)} | ${p.shared} | \`${p.a.path}\` (${p.a.lines}L) | \`${p.b.path}\` (${p.b.lines}L) |`).join('\n')}
`

writeFileSync(OUT, report)
console.log(`wrote ${relative(ROOT, OUT)}: ${files.length} files, ${largest.length} largest, ${mostDuplicated.length} duplicate pairs`)
